<?php require __DIR__.'/includes/config.php'; if(!empty($_SESSION['user'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$q=$pdo->prepare('SELECT id,username,password_hash,role,active FROM users WHERE username=? LIMIT 1');$q->execute([$username]);$u=$q->fetch();if($u && (int)$u['active']===1 && password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'username'=>$u['username'],'role'=>$u['role']];header('Location: index.php');exit;}$error='Identifiant ou mot de passe incorrect.';} $pageTitle='Connexion';require __DIR__.'/includes/header.php'; ?><div class="min-h-[70vh] flex items-center justify-center"><div class="card w-full max-w-md p-6 sm:p-8"><div class="text-xs font-bold tracking-[.2em] brand mb-3">KROON · TERRAIN</div><h1 class="text-2xl font-extrabold">Connectez-vous</h1><p class="text-stone-500 mt-2 mb-6">Suivi des installations de têtes de gondole.</p><?php if($error):?><p class="mb-4 rounded-lg bg-red-50 text-red-800 p-3 text-sm"><?=e($error)?></p><?php endif;?><form method="post" class="space-y-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="block text-sm font-semibold">Identifiant<input name="username" required autocomplete="username" class="mt-1 w-full rounded-xl border border-stone-300 p-3"></label><label class="block text-sm font-semibold">Mot de passe / PIN<input name="password" type="password" required autocomplete="current-password" class="mt-1 w-full rounded-xl border border-stone-300 p-3"></label><button class="btn w-full">Se connecter</button></form></div></div><?php require __DIR__.'/includes/footer.php'; ?>